const {test}=require('node:test');
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {JSDOM,VirtualConsole}=require('jsdom');
const html=fs.readFileSync(path.join(__dirname,'../index.html'),'utf8');
const id=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0');
const D=id(1),S=id(2),OLD=id(3),ME=id(4),THEM=id(5),OWN=id(6),OPP=id(7),CPU=id(8),GAME=id(9),PROGRAM=id(10);
const fixture={dynasties:[{dynasty_id:D,name:'Fixture League',role:'member',status:'active'}],seasons:[{dynasty_id:D,season_id:S,season_number:2,status:'active',is_active:true},{dynasty_id:D,season_id:OLD,season_number:1,status:'completed',is_active:false}],programs:[{dynasty_id:D,season_id:S,season_program_id:PROGRAM,team_id:OWN,team_name:'UConn',coach_name:'Corey',person_id:ME,conference:'American'},{dynasty_id:D,season_id:S,season_program_id:id(11),team_id:OPP,team_name:'Army',coach_name:'Pete',person_id:THEM,conference:'American'}],standings:[{team_id:OWN,team_name:'UConn',person_id:ME,wins:2,losses:0,games_played:2,points_for:70,points_against:21}],scheduleGames:[{id:GAME,dynasty_id:D,season_id:S,week_number:0,status:'scheduled',game_type:'conference',team_id:OWN,team_name:'UConn',person_id:ME,season_program_id:PROGRAM,opponent_team_id:CPU,opponent_team:'Navy',opponent_person_id:null,primary_side:'away',home_away:'away',points_for:null,points_against:null,team_rank:17,opponent_rank:null,team_conference:'American',opponent_conference:'American'}],career:[{person_id:ME,coach_name:'Corey',wins:12,losses:4},{person_id:THEM,coach_name:'Pete',wins:10,losses:6}],trophies:[{id:id(20),person_id:ME,name:'Conference champion',type:'conference_champion',season_number:1,coach_name:'Corey',team_name:'UConn'}],teams:[{id:OWN,name:'UConn',espn_team_id:41,conference:'American'},{id:OPP,name:'Army',espn_team_id:349,conference:'American'},{id:CPU,name:'Navy',espn_team_id:2426,conference:'American'}],myPrograms:[{dynasty_id:D,season_id:S,season_program_id:PROGRAM,team_id:OWN,team_name:'UConn',person_id:ME,conference:'American'}]};
fixture.artworks=[{team_id:OWN,image_url:'https://art.foundry.test/uconn.webp',alt_text:'UConn helmet editorial artwork',accent_color:'#173656'}];
fixture.careerHub={active_game_edition_year:2027,coach:{person_id:ME,name:'Corey'},totals:{wins:20,losses:10,ties:1,seasons:3,national_titles:1,conference_titles:1,heismans:0,draft_picks:1,awards:1,bowl_wins:2,bowl_losses:1,playoff_wins:1,playoff_losses:1,scored_games:30,points_for:900,points_against:600},editions:[{game_edition_year:2027,wins:12,losses:4},{game_edition_year:2026,wins:8,losses:6,ties:1}],chapters:[{dynasty_id:D,game_edition_year:2027,dynasty_name:'Fixture League',wins:12,losses:4,status:'active'},{dynasty_id:id(70),game_edition_year:2026,dynasty_name:'Old League',wins:8,losses:6,ties:1,status:'archived',retired:true}],timeline:[{dynasty_id:D,dynasty_name:'Fixture League',season_id:OLD,game_edition_year:2027,edition_season_number:0,year:2027,team_id:CPU,team_name:'Navy',wins:4,losses:2},{dynasty_id:D,dynasty_name:'Fixture League',season_id:S,game_edition_year:2027,edition_season_number:1,year:2028,team_id:OWN,team_name:'UConn',wins:8,losses:2},{dynasty_id:id(70),dynasty_name:'Old League',season_id:id(71),game_edition_year:2026,edition_season_number:1,year:2026,team_id:CPU,team_name:'Navy',wins:8,losses:6,ties:1}],honors:[{id:id(75),dynasty_id:D,game_edition_year:2027,name:'Conference Championship',type:'conference_championship',team_name:'UConn',edition_season_number:1,year:2028},{id:id(76),dynasty_id:id(70),game_edition_year:2026,name:'National Championship',type:'national_championship',team_name:'Navy',edition_season_number:1,year:2026,points_for:31,points_against:24,opponent_team:'Army'},{id:id(77),dynasty_id:id(70),game_edition_year:2026,name:'Heisman',type:'player_award',recipient_name:'Corey',metadata:{historical_count_import:true}}],facts:[{kind:'draft_pick',dynasty_id:D,game_edition_year:2027,edition_season_number:1,year:2028,recipient_name:'Test Player',label:'NFL Draft',value:1,metadata:{pick:10}},{kind:'stat_leader',dynasty_id:id(70),game_edition_year:2026,edition_season_number:1,year:2026,recipient_name:'Test Quarterback',label:'Passing touchdowns',value:35}]};
const tick=()=>new Promise(r=>setTimeout(r,15));
async function app(options={}){const calls=[],errors=[],vc=new VirtualConsole();vc.on('jsdomError',e=>{if(!/CSS stylesheet|Not implemented/.test(e.message))errors.push(e.message)});const f=structuredClone(fixture);if(options.noTeam)f.myPrograms=[];if(options.commissioner)f.dynasties[0].role='commissioner';if(options.coachStreams)f.coachStreams=options.coachStreams;if(options.extraGames)f.scheduleGames.push(...options.extraGames);let interceptor=options.intercept;
 const dom=new JSDOM(html,{url:'https://foundry.test/index.html',runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(w){w.matchMedia=()=>({matches:true});w.HTMLElement.prototype.scrollIntoView=function(){};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false};w.AbortController=AbortController;w.WebSocket=class{constructor(){this.readyState=0;w.testCareerSocket=this;this.sent=[]}send(v){this.sent.push(JSON.parse(v))}close(){this.closed=true;this.readyState=3;this.onclose?.()}};
 if(!options.signedOut){w.localStorage.setItem('cdhq_supabase_session_v1',JSON.stringify({access_token:'fixture-access-token',user:{id:id(99),email:'fixture@example.invalid'}}));w.localStorage.setItem('sf_graphite_context_v1',JSON.stringify(options.preference||{dynasty:D}));}
 w.fetch=async(url,opts)=>{const u=new URL(url),name=u.pathname.split('/').at(-1),body=opts.body?JSON.parse(opts.body):undefined;calls.push({name,path:u.pathname,method:opts.method,body});if(interceptor){const r=await interceptor({name,body,opts,url});if(r)return r}
 const map={v_my_dynasties:f.dynasties,v_dynasty_seasons:f.seasons,v_season_programs:f.programs,v_program_standings:f.standings,v_schedule_entries:f.scheduleGames,v_coach_career_stats:f.career,v_trophy_room:f.trophies,v_my_programs:f.myPrograms,v_game_entries:[],team_artwork_catalog:f.artworks,teams:f.teams,weekly_story_editions:[],weekly_rankings:[],get_coach_career_stops:[],get_my_coach_career_hub:f.careerHub,get_dynasty_active_week:0,get_dynasty_coaches:f.coachStreams||[],get_h2h_results:{ready:true,results:[]},get_team_selection:[{team_id:OWN,team_name:'UConn',conference:'American',claimed:true,claimed_by:'Corey'},{team_id:CPU,team_name:'Navy',conference:'American',claimed:false}],get_schedule_team_options:[{team_id:CPU,team_name:'Navy',conference:'American'}]};let data=name==='user'?{id:id(99),email:'fixture@example.invalid'}:map[name]||[];if(Array.isArray(data)){const offset=Number(u.searchParams.get('offset')||0);data=data.slice(offset,offset+Number(u.searchParams.get('limit')||500))}return {ok:true,text:async()=>JSON.stringify(data)}}}});
 for(let i=0;i<80&&dom.window.eval('busy');i++)await tick();await tick();return {w:dom.window,dom,calls,errors,f,setInterceptor(fn){interceptor=fn}};
}
function fill(w,name,value){w.document.querySelector(`[name="${name}"]`).value=value}
function click(w,text){const b=[...w.document.querySelectorAll('button')].find(b=>b.textContent.trim()===text);assert(b,`Button ${text}`);b.click()}
function visible(w){return w.document.querySelector('#app').textContent}

test('season shortcuts require a commissioner and direct active-season tools to the correct section',async t=>{
 const a=await app();t.after(()=>a.w.close());a.w.go('office');assert.doesNotMatch(visible(a.w),/Start next season/);
 a.w.openAdvanced('admin','season');assert.equal(a.w.eval('route'),'office');
 a.f.dynasties[0].role='commissioner';a.w.eval("dynasty.role='commissioner';render()");a.w.document.querySelector('[onclick="openAdvanced(\'admin\',\'season\')"]').click();
 let params=new URL(a.w.document.querySelector('iframe').src).searchParams;
 assert.equal(params.get('dynasty'),D);assert.equal(params.get('season'),S);assert.equal(params.get('focus'),'season');
 await a.w.go('office');a.w.document.querySelector('[onclick="openAdvanced(\'admin\',\'program\')"]').click();params=new URL(a.w.document.querySelector('iframe').src).searchParams;assert.equal(params.get('focus'),'program');
 await a.w.go('home');await a.w.loadSeason(OLD);a.w.go('office');assert.doesNotMatch(visible(a.w),/Start next season/);assert.match(visible(a.w),/Open the active season/);
 assert.deepEqual(a.errors,[]);
});

test('returning from rollover follows the new active season and archive visits never become the Home preference',async t=>{
 const a=await app({commissioner:true});t.after(()=>a.w.close());const NEXT=id(130),FL=id(131);
 assert.equal(JSON.parse(a.w.localStorage.getItem('sf_graphite_context_v1')).followActiveSeason,true);
 a.w.openAdvanced('admin','season');
 a.f.seasons.find(s=>s.season_id===S).is_active=false;a.f.seasons.find(s=>s.season_id===S).status='completed';
 a.f.seasons.unshift({dynasty_id:D,season_id:NEXT,season_number:3,status:'active',is_active:true});
 a.f.dynasties[0].active_season_id=NEXT;a.f.dynasties[0].active_season_number=3;
 a.f.myPrograms.push({...fixture.myPrograms[0],season_id:NEXT,team_id:FL,team_name:'Florida'});
 a.w.eval(`model.teams.push({id:'${FL}',name:'Florida',espn_team_id:57})`);
 a.setInterceptor(({name,url})=>{
  const sid=new URL(url).searchParams.get('season_id')?.slice(3);
  if(name==='v_season_programs')return {ok:true,text:async()=>JSON.stringify([{...fixture.programs[0],season_id:sid,team_id:sid===NEXT?FL:OWN,team_name:sid===NEXT?'Florida':'UConn'}])};
  if(name==='v_schedule_entries')return {ok:true,text:async()=>JSON.stringify(sid===NEXT?[]:[{...fixture.scheduleGames[0],season_id:sid,status:'completed',points_for:28,points_against:7}])};
 });
 await a.w.go('home');assert.equal(a.w.eval('season.season_id'),NEXT);assert.equal(a.w.eval('myTeam()'),FL);
 a.w.go('leagues');await a.w.refreshLeagueCards();assert.match(a.w.document.querySelector('.league-team-name').textContent,/Florida/);assert.match(a.w.document.querySelector('.league-team-badge').src,/\/57\.png$/);
 await a.w.loadSeason(S);assert.equal(a.w.eval('myTeam()'),OWN);assert.equal(JSON.parse(a.w.localStorage.getItem('sf_graphite_context_v1')).followActiveSeason,true);assert.equal(a.w.eval('route'),'seasonarchive');
 await a.w.loadDynasty(D);assert.equal(a.w.eval('season.season_id'),NEXT);assert.equal(a.w.eval('myTeam()'),FL);
 assert.equal(a.w.eval('model.career.find(c=>c.person_id===myCoach()).wins'),12);
 assert.deepEqual(a.errors,[]);
});

test('login, signup and empty accounts have usable entry screens',async t=>{const a=await app({signedOut:true});t.after(()=>a.w.close());assert.match(visible(a.w),/Welcome back/);assert.equal(a.calls.length,0);a.w.toggleAuth('signup');assert(a.w.document.querySelector('[name="displayName"]'));assert(a.w.document.querySelector('[autocomplete="new-password"]'));assert.deepEqual(a.errors,[])});
test('live loader, five destinations and all reading routes stay consistent',async t=>{const a=await app();t.after(()=>a.w.close());assert.equal(a.w.eval('season.season_id'),S);assert.equal(a.w.eval('week'),0);assert.equal(a.w.eval('myTeam()'),OWN);const lists=[...a.w.document.querySelectorAll('nav[aria-label="Main navigation"]')];assert.equal(lists.length,2);assert.equal(lists[0].textContent,lists[1].textContent);for(const r of ['home','scores','teams','team','coach','standings','legacy','trophies','stories','article','game','account','leagues','seasons','rankings','analysis','rivalries','career','explore','joinleague','createleague']){a.w.go(r);assert(!visible(a.w).includes('This screen could not load'),r)}assert.deepEqual(a.errors,[])});
test('score review preserves zero, maps away ownership, and writes only after confirmation',async t=>{const a=await app();t.after(()=>a.w.close());a.w.beginResult(GAME);fill(a.w,'awayScore','0');fill(a.w,'homeScore','21');a.w.reviewResult(a.w.document.querySelector('form'));assert.equal(a.w.eval('route'),'resultreview');assert.equal(a.calls.filter(c=>c.name==='submit_game_result').length,0);await a.w.saveResult(a.w.document.querySelector('form'));const saved=a.calls.find(c=>c.name==='submit_game_result');assert.equal(saved.body.p_my_score,0);assert.equal(saved.body.p_opponent_score,21);assert.equal(saved.body.p_my_rank,17);assert.equal(saved.body.p_opponent_rank,null);assert.match(visible(a.w),/Final score saved/)});
test('tied scores and changed seasons cannot be submitted',async t=>{const a=await app();t.after(()=>a.w.close());a.w.beginResult(GAME);fill(a.w,'awayScore','17');fill(a.w,'homeScore','17');a.w.reviewResult(a.w.document.querySelector('form'));assert.match(a.w.document.querySelector('#formMessage').textContent,/non-tied/);assert.equal(a.w.eval('route'),'result');fill(a.w,'homeScore','24');a.w.reviewResult(a.w.document.querySelector('form'));const form=a.w.document.querySelector('form');a.w.eval(`season={...season,season_id:'${OLD}',status:'completed',is_active:false}`);await a.w.saveResult(form);assert.equal(a.calls.filter(c=>c.name==='submit_game_result').length,0);assert.match(form.textContent,/no longer/)});
test('CPU games and unavailable H2H service never expose result entry',async t=>{const a=await app();t.after(()=>a.w.close());a.w.eval(`model.myPrograms=[]`);a.w.beginResult(GAME);assert.notEqual(a.w.eval('route'),'result');a.w.eval(`model.myPrograms=[{season_id:'${S}',team_id:'${OWN}',person_id:'${ME}'}];model.scheduleGames[0].opponent_team_id='${OPP}';h2hMeta={ready:false,results:[]}`);a.w.beginResult(GAME);assert.notEqual(a.w.eval('route'),'result')});
test('failed and duplicate score saves do not retry or lose the draft',async t=>{const a=await app();t.after(()=>a.w.close());let finish;a.setInterceptor(({name})=>name==='submit_game_result'?new Promise(r=>finish=()=>r({ok:false,status:409,text:async()=>JSON.stringify({message:'Final already entered'})})):null);a.w.beginResult(GAME);fill(a.w,'awayScore','14');fill(a.w,'homeScore','7');a.w.reviewResult(a.w.document.querySelector('form'));const form=a.w.document.querySelector('form'),p=a.w.saveResult(form);await tick();await a.w.saveResult(form);assert.equal(a.calls.filter(c=>c.name==='submit_game_result').length,1);finish();await p;assert.match(form.textContent,/Final already entered/);assert.equal(a.w.eval('resultDraft.away'),14);assert.equal(a.w.eval('mutationPending'),false)});
test('team selection shows claims and requires explicit confirmation to save',async t=>{const a=await app({noTeam:true});t.after(()=>a.w.close());await a.w.openTeamSelection();a.w.chooseProgram(OWN);assert.equal(a.w.eval('route'),'selectteam');a.w.chooseProgram(CPU);assert.equal(a.w.eval('route'),'claimreview');assert.equal(a.calls.filter(c=>c.name==='claim_team').length,0);await a.w.claimProgram(a.w.document.querySelector('form'));const c=a.calls.find(c=>c.name==='claim_team');assert.equal(c.body.p_team_id,CPU);assert.equal(c.body.p_season_id,S)});
test('claim race errors retain the chosen program and never create a fake assignment',async t=>{const a=await app({noTeam:true,intercept:({name})=>name==='claim_team'?{ok:false,status:409,text:async()=>JSON.stringify({message:'That team was just claimed by another user'})}:null});t.after(()=>a.w.close());await a.w.openTeamSelection();a.w.chooseProgram(CPU);await a.w.claimProgram(a.w.document.querySelector('form'));assert.match(visible(a.w),/just claimed/);assert.equal(a.w.eval('myTeam()'),null)});
test('H2H validation uses saved scores and version and requires a note for disputes',async t=>{const a=await app();t.after(()=>a.w.close());a.w.eval(`model.scheduleGames[0]={...model.scheduleGames[0],status:'completed',points_for:7,points_against:14,opponent_team_id:'${OPP}'};h2hMeta={ready:true,results:[{game_id:'${GAME}',status:'pending',opponent_person:'${ME}',submitted_by:'${THEM}',submitted_name:'Pete',home_score:14,away_score:7,version:3}]}`);a.w.validateDialog(GAME);const form=a.w.document.querySelector('#validationForm');await a.w.validateFinal(GAME,false,form);assert.match(form.textContent,/Describe/);assert.equal(a.calls.filter(c=>c.name==='validate_h2h_result').length,0);await a.w.validateFinal(GAME,true,form);const b=a.calls.find(c=>c.name==='validate_h2h_result').body;assert.equal(b.p_version,3);assert.equal(b.p_home_score,14);assert.equal(b.p_away_score,7);assert.equal(b.p_confirm,true)});
