test('optional read failures show warnings while required failures stop partial league rendering',async t=>{const fail={ok:false,status:503,text:async()=>JSON.stringify({message:'Fixture unavailable'})};const a=await app({intercept:({name})=>name==='weekly_rankings'?fail:null});t.after(()=>a.w.close());assert.match(visible(a.w),/Rankings is temporarily unavailable/);assert.match(visible(a.w),/Your league, your Saturday/);a.setInterceptor(({name})=>name==='v_schedule_entries'?fail:null);await a.w.loadSeason(S);assert.match(visible(a.w),/Connection interrupted/);assert(!a.w.document.querySelector('.sports-card'))});
test('archived seasons expose no score entry or schedule mutation actions',async t=>{const a=await app();t.after(()=>a.w.close());await a.w.loadSeason(OLD);assert.equal(a.w.eval('season.season_id'),OLD);assert(![...a.w.document.querySelectorAll('button')].some(b=>b.textContent==='Enter final score'));a.w.go('scores');assert(![...a.w.document.querySelectorAll('button')].some(b=>b.textContent==='Add a matchup'));assert.equal(a.w.eval('scoreEntryAllowed(games()[0])'),false)});
