test('a rejected login stays usable and exposes no private data',async t=>{const a=await app({signedOut:true,intercept:({name})=>name==='token'?{ok:false,status:400,text:async()=>JSON.stringify({message:'Invalid login credentials'})}:null});t.after(()=>a.w.close());fill(a.w,'email','test@example.invalid');fill(a.w,'password','not-a-real-password');await a.w.login(a.w.document.querySelector('form'));assert.match(visible(a.w),/Invalid login credentials/);assert.equal(a.w.document.querySelector('button[type=submit]').disabled,false);assert.equal(a.w.eval('session()'),null)});
test('signup confirmation never pretends a user is signed in',async t=>{const a=await app({signedOut:true,intercept:({name})=>name==='signup'?{ok:true,text:async()=>JSON.stringify({user:{id:id(99)}})}:null});t.after(()=>a.w.close());a.w.toggleAuth('signup');fill(a.w,'displayName','Coach');fill(a.w,'email','test@example.invalid');fill(a.w,'password','not-a-real-password');await a.w.signup(a.w.document.querySelector('form'));assert.match(visible(a.w),/Check your email/);assert.equal(a.w.eval('session()'),null);assert.equal(a.w.document.querySelector('[name=password]').value,'')});
test('session refresh is single flight and never restores a logged-out session',async t=>{const a=await app();t.after(()=>a.w.close());a.w.eval("save({...session(),refresh_token:'old-refresh'})");let finish;a.setInterceptor(({name})=>name==='token'?new Promise(r=>finish=()=>r({ok:true,text:async()=>JSON.stringify({access_token:'new-access',refresh_token:'new-refresh'})})):null);const p=a.w.refreshAuthSingleFlight(),q=a.w.refreshAuthSingleFlight();await tick();assert.equal(a.calls.filter(c=>c.name==='token').length,1);a.w.eval('save(null)');finish();await assert.rejects(()=>p,/expired/);await assert.rejects(()=>q,/expired/);assert.equal(a.w.eval('session()'),null)});
test('a lost mutation response never auto-retries',async t=>{const a=await app();t.after(()=>a.w.close());a.setInterceptor(({name})=>{if(name==='submit_game_result')throw new a.w.TypeError('Network lost');return null});a.w.beginResult(GAME);fill(a.w,'awayScore','14');fill(a.w,'homeScore','7');a.w.reviewResult(a.w.document.querySelector('form'));await a.w.saveResult(a.w.document.querySelector('form'));assert.equal(a.calls.filter(c=>c.name==='submit_game_result').length,1);assert.match(visible(a.w),/Network lost/)});
test('league and season switching are blocked while a score is saving',async t=>{const a=await app();t.after(()=>a.w.close());let finish;a.setInterceptor(({name})=>name==='submit_game_result'?new Promise(r=>finish=()=>r({ok:false,status:409,text:async()=>JSON.stringify({message:'Try again'})})):null);a.w.beginResult(GAME);fill(a.w,'awayScore','14');fill(a.w,'homeScore','7');a.w.reviewResult(a.w.document.querySelector('form'));const form=a.w.document.querySelector('form'),p=a.w.saveResult(form);await tick();await a.w.loadSeason(OLD);await a.w.loadDynasty(D);await a.w.start();a.w.go('home');assert.equal(a.w.document.querySelector('form'),form);assert.equal(a.w.eval('season.season_id'),S);finish();await p});

test('persistent Commish shortcut opens office and follows selected league permissions',async t=>{const a=await app({commissioner:true});t.after(()=>a.w.close());for(const route of ['home','scores','teams','standings','legacy']){a.w.go(route);const b=a.w.document.querySelector('.mast .commish-shortcut');assert(b,route);assert.equal(b.getAttribute('aria-label'),'Commissioner office');b.click();assert.equal(a.w.eval('route'),'office');assert.match(visible(a.w),/League office/)}a.w.eval("dynasty.role='co_commissioner';render()");assert(a.w.document.querySelector('.commish-shortcut'));a.w.eval("dynasty.role='member';render()");assert(!a.w.document.querySelector('.commish-shortcut'));await a.w.logout();assert(!a.w.document.querySelector('.commish-shortcut'))});

test('report never renders saved filler or old image thumbnails',async t=>{const a=await app();t.after(()=>a.w.close());a.w.eval("model.stories=[{payload:{lead:{headline:'Army: the weekly desk'}}}];render()");const report=a.w.document.querySelector('#saturdayReport');assert(!report.textContent.includes('weekly desk'));assert(!report.querySelector('img[src*=stadium]'));assert.match(report.textContent,/UConn at Navy/);a.w.eval("model.scheduleGames=[];render()");assert.match(a.w.document.querySelector('#saturdayReport').textContent,/Your next story starts/)});

test('commissioner report edits use scoped server RPC and preserve errors; members have no editor',async t=>{const a=await app({commissioner:true});t.after(()=>a.w.close());a.w.openReportEditor();let form=a.w.document.querySelector('[data-report-editor]');assert(form);a.setInterceptor(({name,body})=>name==='set_preview_report_story'?{ok:true,text:async()=>JSON.stringify({season_id:S,week_number:0,pinned_id:body.p_story_id,hidden_ids:[],revision:2})}:null);await a.w.saveReportChoice('pin','preview:'+GAME,form);const call=a.calls.find(c=>c.name==='set_preview_report_story');assert.equal(call.body.p_season_id,S);assert.equal(call.body.p_week,0);assert.equal(a.w.eval('reportSelection().lead.id'),'preview:'+GAME);a.w.openReportEditor();form=a.w.document.querySelector('[data-report-editor]');a.setInterceptor(({name})=>name==='set_preview_report_story'?{ok:false,status:409,text:async()=>JSON.stringify({message:'The report changed. Refresh before editing.'})}:null);await a.w.saveReportChoice('hide','preview:'+GAME,form);assert.match(form.textContent,/report changed/);assert.equal(a.w.eval('reportSelection().lead.id'),'preview:'+GAME);a.w.closeSheet();a.w.eval("dynasty.role='member';render()");assert(!a.w.document.querySelector('#saturdayReport').textContent.includes('Edit report'));a.w.openReportEditor();assert(!a.w.document.querySelector('#detailSheet').open)});

test('report refresh tracks other users results and active week without overwriting open forms',async t=>{const a=await app();t.after(()=>a.w.close());a.f.scheduleGames[0].status='completed';a.f.scheduleGames[0].points_for=49;a.f.scheduleGames[0].points_against=7;await a.w.refreshReport(true);assert.match(a.w.document.querySelector('#saturdayReport').textContent,/49–7/);a.setInterceptor(({name})=>name==='get_dynasty_active_week'?{ok:true,text:async()=> '1'}:null);await a.w.refreshReport(true);assert.equal(a.w.eval('week'),1);a.w.go('addgame');const form=a.w.document.querySelector('form');await a.w.refreshReport(true);assert.equal(a.w.document.querySelector('form'),form)});

test('league picker loads each active-season team before that league is opened and ignores archive selection',async t=>{const D2=id(70),S2=id(71),programs=[{...fixture.myPrograms[0]},{...fixture.myPrograms[0],season_id:OLD,team_id:CPU,team_name:'Navy'},{...fixture.myPrograms[0],dynasty_id:D2,season_id:S2,team_id:OPP,team_name:'Army'}];const a=await app({intercept:({name,url})=>{if(name==='v_my_dynasties')return {ok:true,text:async()=>JSON.stringify([{...fixture.dynasties[0],active_season_id:S,active_season_number:2},{dynasty_id:D2,name:'Other League',active_season_id:S2,active_season_number:5,role:'member'}])};if(name==='v_my_programs'){const d=new URL(url).searchParams.get('dynasty_id')?.slice(3);return {ok:true,text:async()=>JSON.stringify(d?programs.filter(p=>p.dynasty_id===d):programs)}}}});t.after(()=>a.w.close());a.w.go('leagues');await tick();const card=id=>a.w.document.querySelector(`[data-league="${id}"]`);assert.match(card(D).textContent,/UConn/);assert.match(card(D).querySelector('img').src,/\/41\.png$/);assert.match(card(D2).textContent,/Army/);assert.match(card(D2).querySelector('img').src,/\/349\.png$/);a.w.eval(`season=model.seasons.find(s=>s.season_id==='${OLD}');render()`);assert.match(card(D).querySelector('img').src,/\/41\.png$/);assert(!card(D).querySelector('img').src.includes('stadium'))});

test('league picker refresh follows rollover and never reuses the previous season team when unassigned',async t=>{const a=await app();t.after(()=>a.w.close());a.f.dynasties[0].active_season_id=S;a.f.dynasties[0].active_season_number=2;a.w.go('leagues');await a.w.refreshLeagueCards();assert.match(a.w.document.querySelector('.league-team-name').textContent,/UConn/);a.f.dynasties[0].active_season_id=id(80);a.f.dynasties[0].active_season_number=3;await a.w.refreshLeagueCards();assert.match(a.w.document.querySelector('.league-team-name').textContent,/No team selected/);assert.match(a.w.document.querySelector('.league-team-badge').src,/foundry-shield.webp$/);a.f.myPrograms.push({...fixture.myPrograms[0],season_id:id(80),team_id:OPP,team_name:'Army'});await a.w.refreshLeagueCards();assert.match(a.w.document.querySelector('.league-team-name').textContent,/Army/);assert.match(a.w.document.querySelector('.league-team-badge').src,/\/349\.png$/);await a.w.logout();assert.equal(a.w.eval('model.leaguePrograms.length'),0)});

test('season program changes switch personal team and report art while archives retain the original team',async t=>{const a=await app();t.after(()=>a.w.close());const UNC=id(90);a.f.seasons.find(s=>s.season_id===OLD).status='archived';a.f.teams.push({id:UNC,name:'North Carolina',espn_team_id:153});a.w.eval(`model.teams.push({id:'${UNC}',name:'North Carolina',espn_team_id:153})`);a.f.myPrograms=[{...fixture.myPrograms[0],season_id:S,team_id:UNC,team_name:'North Carolina'},{...fixture.myPrograms[0],season_id:OLD}];a.setInterceptor(({name,url})=>{const sid=new URL(url).searchParams.get('season_id')?.slice(3),old=sid===OLD;if(name==='v_season_programs'){assert.equal(new URL(url).searchParams.get('active'),old?null:'eq.true');return {ok:true,text:async()=>JSON.stringify([{...fixture.programs[0],active:!old,season_id:sid,team_id:old?OWN:UNC,team_name:old?'UConn':'North Carolina'}])}};if(name==='v_schedule_entries')return {ok:true,text:async()=>JSON.stringify([{...fixture.scheduleGames[0],season_id:sid,team_id:old?OWN:UNC,team_name:old?'UConn':'North Carolina',status:'completed',points_for:28,points_against:7}])}});await a.w.loadDynasty(D);await tick();assert.equal(a.w.eval('myTeam()'),UNC);assert.match(a.w.document.querySelector('#saturdayReport').textContent,/North Carolina/);assert(!a.w.document.querySelector('#saturdayReport img[src$="uconn.webp"]'));assert(a.w.document.querySelector('#saturdayReport img[src$="153.png"]'));await a.w.loadSeason(OLD);await tick();assert.equal(a.w.eval('myTeam()'),OWN);a.w.go('stories');assert(a.w.document.querySelector('#saturdayReport img[src$="uconn.webp"]'));assert.equal(a.w.eval('model.career.find(c=>c.person_id===myCoach()).wins'),12)});


