test('catalog refresh deduplicates reads, preserves score drafts and ignores logged-out responses',async t=>{
 const a=await app();t.after(()=>a.w.close());let finish;const before=a.calls.filter(c=>c.name==='team_artwork_catalog').length;
 a.setInterceptor(({name})=>name==='team_artwork_catalog'?new Promise(r=>finish=()=>r({ok:true,text:async()=>JSON.stringify([{...fixture.artworks[0],image_url:'https://art.foundry.test/new.webp'}])})):null);
 await a.w.loadTeamArtwork();assert.equal(a.calls.filter(c=>c.name==='team_artwork_catalog').length,before);
 const p=a.w.loadTeamArtwork(true),q=a.w.loadTeamArtwork(true);await tick();assert.equal(a.calls.filter(c=>c.name==='team_artwork_catalog').length,before+1);
 a.w.beginResult(GAME);fill(a.w,'awayScore','17');const form=a.w.document.querySelector('form');finish();await Promise.all([p,q]);assert.equal(a.w.document.querySelector('form'),form);assert.equal(form.elements.awayScore.value,'17');
 const r=a.w.loadTeamArtwork(true);await tick();await a.w.logout();finish();await r;assert.match(visible(a.w),/Welcome back/);assert(!a.w.document.querySelector('.report-art'));assert.deepEqual(a.errors,[]);
});


